describe('Gravity Wheel mob skill',function()
 it('requires polearm animation sub two and applies Weight only after processed damage',function()
  local wheel=require('scripts/actions/mobskills/gravity_wheel');local move,process,status=xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove;local params,damage,weight=nil,nil,nil;local animation=2;local mob={getAnimationSub=function()return animation end,getWeaponDmg=function()return 77 end};local target={takeDamage=function(_,...)damage={...}end};assert(wheel.onMobSkillCheck(target,mob,{})==0);animation=1;assert(wheel.onMobSkillCheck(target,mob,{})==1);animation=2;xi.mobskills.mobPhysicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.PHYSICAL,damageType=xi.damageType.SLASHING}end;xi.mobskills.processDamage=function()return false end;xi.mobskills.mobStatusEffectMove=function(...)weight={...}end
  assert(wheel.onMobWeaponSkill(mob,target,{},{})==123);assert(params.baseDamage==77 and params.numHits==1 and params.fTP[1]==1 and params.fTP[2]==1 and params.fTP[3]==1 and params.attackType==xi.attackType.PHYSICAL and params.damageType==xi.damageType.SLASHING and params.shadowBehavior==xi.mobskills.shadowBehavior.NUMSHADOWS_2 and damage==nil and weight==nil);xi.mobskills.processDamage=function()return true end;wheel.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove=move,process,status;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.PHYSICAL and damage[4]==xi.damageType.SLASHING and weight[3]==xi.effect.WEIGHT and weight[4]==50 and weight[5]==0 and weight[6]==120)
 end)
end)
